INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 26, 'theory', 'Quiz: System calls');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 26, 0, 'A read on a socket asked for 4096 bytes and returned 3. What does it mean?', '["An error happened, look at errno for the reason", "It is a valid short result: keep reading until you have enough or get 0", "The file has ended", "The peer closed the socket"]', 1, 'A short read is not an error: pipes, terminals and sockets hand over what is already there. End of file and a closed peer are signalled by a zero, and an error by minus one.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 26, 1, 'What does this strace line mean: read(3, "", 4096) = 0?', '["A read error", "A signal interrupted the call, repeat it", "The kernel has not read anything yet", "End of file was reached: no more data will come"]', 3, 'A zero from read is end of file (for a pipe or socket, the other side closed). An error would look like -1 with an errno name, and an interruption like -1 EINTR.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 26, 2, 'Code calls close after a failed read and returns -1. Why can the caller get a wrong errno?', '["Even a successful close may change errno: copy the value right after the failure and restore it", "Every function has its own copy of errno", "errno is reset on every return", "errno is shared by all threads, so there is a race"]', 0, 'errno is meaningful only right after a call that reported an error; a successful call may change it, and the library never resets it to zero. So the value is saved and restored after cleanup. errno is per thread, by the way.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 26, 3, 'A process closed descriptor 0 and immediately called open. Which number comes back?', '["The one after the highest open number", "A random free one", "0: the lowest free number is handed out", "Always 3"]', 2, 'Opening calls return the lowest free descriptor. Redirection rests on this rule: close 0 and open a file, and it becomes the standard input.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 26, 4, 'close returned -1 with EINTR. What should you do on Linux?', '["Repeat close until it returns 0", "Do not repeat: on Linux the descriptor is already closed, and a repeat may close someone else''s", "Assume all the data is safely written", "Restart the process"]', 1, 'According to the man page, on Linux the kernel releases the descriptor in any case, so a second close risks closing a descriptor already handed to another thread. Write reliability is checked with fsync before the close.');
